def rotate_left(xs: list[int], k: int) -> list[int]:
    if not xs or k == 0:
        return xs[:]

    n = len(xs)
    rotated = [0] * n
    for i in range(n):
        rotated[i] = xs[(i + k) % n]

    return rotated
